#game.failure .result { border-color: rgba(255, 120, 105, 0.9); }
#game.failure .result-title { color: #ff8b78; }
#game .player.launch .ball { animation: game-ball-launch 700ms ease-out forwards; }
#game .player.weak .ball { animation: game-ball-weak 550ms ease-in forwards; }
#game .player.over .ball { animation: game-ball-over 600ms ease-in-out forwards; }
@keyframes game-ball-launch { 0% { transform: translate(0,0) scale(1); } 65% { transform: translate(2px,-45px) scale(1.08); } 100% { transform: translate(8px,-58px) scale(0.9); opacity: 0.75; } }
@keyframes game-ball-weak { 0% { transform: translate(0,0); } 100% { transform: translate(0,18px) scale(0.8); opacity: 0.65; } }
@keyframes game-ball-over { 0% { transform: translate(0,0) rotate(0); } 45% { transform: translate(-7px,-18px) rotate(-18deg); } 100% { transform: translate(8px,10px) rotate(25deg); opacity: 0.6; } }
@media (max-height: 360px) { #game .player { transform: scale(0.78); margin-bottom: -8px; } #game .scene { padding-top: 3px; padding-bottom: 3px; } #game .gauge-wrap { transform: scale(0.9); transform-origin: center; } }
